/* Auto-generated by DUANYAN v1.5.0 — chip_info for ESP32-S3
 * Arduino framework version (compiles fast, no ESP-IDF install needed)
 * 功能: ESP32-S3 上电自报家门，通过串口打印全部硬件配置
 */
#include <Arduino.h>
#include "esp_chip_info.h"
#include "esp_flash.h"
#include "esp_system.h"
#include "esp_mac.h"

static const char* chip_model_str(esp_chip_model_t model) {
    switch (model) {
        case CHIP_ESP32:   return "ESP32";
        case CHIP_ESP32S2: return "ESP32-S2";
        case CHIP_ESP32S3: return "ESP32-S3";
        case CHIP_ESP32C3: return "ESP32-C3";
        case CHIP_ESP32C6: return "ESP32-C6";
        case CHIP_ESP32H2: return "ESP32-H2";
        default:           return "Unknown";
    }
}

void setup() {
    Serial.begin(115200);
    delay(1000);  // 等待串口就绪

    // 读取芯片信息
    esp_chip_info_t info;
    esp_chip_info(&info);

    uint32_t flash_size = 0;
    esp_flash_get_size(NULL, &flash_size);

    uint8_t mac[6] = {0};
    esp_efuse_mac_get_default(mac);

    // 自报家门
    Serial.println("================================");
    Serial.println("  ESP32-S3 Self Introduction");
    Serial.println("  Powered by DUANYAN");
    Serial.println("================================");
    Serial.println("");

    Serial.printf("Chip Model    : %s\n", chip_model_str(info.model));
    Serial.printf("Revision      : v%d.%d\n", info.revision / 100, info.revision % 100);
    Serial.printf("CPU Cores     : %d\n", info.cores);
    Serial.printf("CPU Freq      : %d MHz\n", ESP.getCpuFreqMHz());
    Serial.printf("Flash Size    : %d MB\n", flash_size / (1024 * 1024));
    Serial.printf("PSRAM Size    : %d KB\n", ESP.getPsramSize() / 1024);
    Serial.printf("Free Heap     : %d bytes\n", ESP.getFreeHeap());
    Serial.printf("Free PSRAM    : %d bytes\n", ESP.getFreePsram());
    Serial.printf("MAC Address   : %02X:%02X:%02X:%02X:%02X:%02X\n",
                  mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
    Serial.printf("SDK Version   : %s\n", ESP.getSdkVersion());
    Serial.printf("Arduino Core  : %s\n", ESP_ARDUINO_VERSION_STR);

    // WiFi 信息
    Serial.println("");
    Serial.println("--- WiFi ---");
    Serial.printf("WiFi MAC      : %s\n", WiFi.macAddress().c_str());
    Serial.printf("BT MAC        : %s\n", WiFi.BTmacAddress().c_str());

    Serial.println("");
    Serial.println("================================");
    Serial.println("  All systems nominal. Ready!");
    Serial.println("================================");
    Serial.println("");
    Serial.println("[DUANYAN] Awaiting commands...");
}

void loop() {
    // 每 5 秒打印一次心跳
    delay(5000);
    Serial.printf("[heartbeat] free_heap=%d  uptime=%lus\n",
                  ESP.getFreeHeap(), millis() / 1000);
}
